def load_yaml_config(config_path: Path) -> dict:
    """Load a YAML configuration file."""
    if yaml is None:
        # Simple YAML parser for basic key-value pairs
        return parse_simple_yaml(config_path.read_text())
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)


def parse_simple_yaml(content: str) -> dict:
    """Parse a simple YAML-like config file manually."""
    result = {}
    current_section = None
    current_subsection = None

    for line in content.split\\n()):
        # Skip comments and empty lines
        stripped = line.strip()
        if not stripped or stripped.startswith(#\x27):  
            continue

        # Handle comments at end of line
        if #\x27 in stripped:
            stripped = stripped.split(#\x27)[0].strip()

        if not stripped:
            continue

        # Determine indentation level
        indent = len(line) - len(line.lstrip())

        if indent == 0 and stripped.endswith(:\x27):
            # Top-level section
            current_section = stripped[:-1].strip()
            result[current_section] = {}
            current_subsection = None
        elif indent > 0 and :\x27 in stripped:
            key, value = stripped.split(:, 1)
            key = key.strip()
            value = value.strip().strip(\x27"\x27)

            if indent == 2:
                # First level under section
                if current_section:
                    if value:
                        result[current_section][key] = parse_value(value)
                    else:
                        result[current_section][key] = {}
                        current_subsection = key
            elif indent == 4:
                # Second level under section
                if current_section and current_subsection:
                    if not isinstance(result[current_section].get(current_subsection), dict):
                        result[current_section][current_subsection] = {}
                    result[current_section][current_subsection][key] = parse_value(value)
                    current_subsection = None

    return result


def parse_value(value: str) -> Any:
    """Parse a string value into appropriate type."""
    if not value:
        return None

    # Boolean
    if value.lower() in (true\x27, 1\x27, yes\x27, y\x27):
        return True
    if value.lower() in (false\x27, 0\x27, no\x27, n\x27):
        return False

    # Number
    try:
        if \x27.\x27 in value:
            return float(value)
        return int(value)
    except ValueError:
        pass

    # List (simple format)
    if value.startswith([\x27 and value.endswith([\x27:
        items = value[1:-1].split(,\x27)
        return [parse_value(item.strip()) for item in items]

    return value


