    def _execute_trades(self, date: str, market_prices: Dict[str, float], 
                        prev_closes: Dict[str, float]) -> List[Trade]:
        """
        Execute trades based on strategy signals.
        """
        trades_executed = []

        # Check risk limits
        portfolio_value = self.engine.get_portfolio_value(market_prices)
        daily_pnl = portfolio_value - self.strategy.daily_start_value

        if self.strategy.check_risk_limits(portfolio_value, daily_pnl):
            print(f"  Risk limit breached on {date}")
            return trades_executed

        # Calculate current position value
        position_value = sum(
            pos.total * market_prices.get(pos.stock, 0)
            for pos in self.engine.positions.values()
        )
        position_ratio = position_value / portfolio_value if portfolio_value > 0 else 0

        # Find stocks to buy
        stocks_to_buy = []
        stocks_to_sell = []

        for stock in self.stock_data.keys():
            signal = self.strategy.stock_signals.get(stock, 'hold')
            if signal == 'buy':
                # Check if we're under max total position
                if position_ratio < self.strategy.max_total_position:
                    # Check if we already own this stock
                    if stock not in self.engine.positions or self.engine.positions[stock].total == 0:
                        stocks_to_buy.append(stock)
            elif signal == 'sell':
                if stock in self.engine.positions and self.engine.positions[stock].total > 0:
                    stocks_to_sell.append(stock)
            elif signal == 'partial_sell':
                if stock in self.engine.positions and self.engine.positions[stock].total > 0:
                    stocks_to_sell.append((stock, self.partial_exit))

        # Limit number of new positions
        if len(stocks_to_buy) > self.strategy.max_stocks - len(self.engine.positions):
            # Sort by momentum and take top ones
            stocks_to_buy.sort(key=lambda s: 
                self.strategy.calculate_momentum(s) or 0, reverse=True)
            stocks_to_buy = stocks_to_buy[:self.strategy.max_stocks - len(self.engine.positions)]

        # Execute sell orders first (to free up capital)
        for item in stocks_to_sell:
            if isinstance(item, tuple):
                stock, fraction = item
            else:
                stock = item
                fraction = 1.0

            pos = self.engine.positions.get(stock)
            if pos and pos.total > 0:
                sell_qty = int(pos.available * fraction)
                if sell_qty >= 100:
                    price = market_prices.get(stock, pos.avg_cost)
                    trade = self.engine.place_order(date, stock, 'sell', price, sell_qty,
                                                   prev_closes.get(stock))
                    if trade:
                        trades_executed.append(trade)
                        print(f"  SOLD {trade.stock}: {trade.quantity} @ {trade.price:.2f}")
                        self.strategy.remove_position(stock)

        # Execute buy orders
        for stock in stocks_to_buy:
            price = market_prices.get(stock, 0)
            if price > 0:
                # Calculate position size
                qty = self.strategy.get_position_size(stock, price, portfolio_value)

                # Check price limit
                if prev_closes.get(stock):
                    if not self.engine.is_within_price_limit(stock, price, prev_closes[stock]):
                        print(f"  SKIPPED {stock}: price at limit")
                        continue

                trade = self.engine.place_order(date, stock, 'buy', price, qty,
                                               prev_closes.get(stock))
                if trade:
                    trades_executed.append(trade)
                    print(f"  BOUGHT {trade.stock}: {trade.quantity} @ {trade.price:.2f}")
                    self.strategy.set_entry_price(stock, price)

        return trades_executed
